"""Validate emitted N64 layout constants, including three genuine negative controls."""
import struct
from pathlib import Path
HERE=Path(__file__).resolve().parent
FACTS=[('visual_bytes','sizeof(Effect)',24),('visual_view','OFF(Effect,view)',4),('visual_mesh','OFF(Effect,mesh)',6),('visual_player','OFF(Effect,player)',8),('visual_data','OFF(Effect,data)',12),('visual_time','OFF(Effect,time)',16),('visual_callback','OFF(Effect,callback)',20),('car_bytes','sizeof(CAR_DATA)',952),('car_pos','OFF(CAR_DATA,pos)',8),('car_hidden','OFF(CAR_DATA,hidden)',856),('car_flags','OFF(CAR_DATA,flags)',908),('car_color','OFF(CAR_DATA,color_index)',928),('car_alpha','OFF(CAR_DATA,alpha)',929),('car_alpha_mode','OFF(CAR_DATA,alpha_mode)',930),('vehicle_bytes','sizeof(MODELDAT)',2056),('vehicle_state','OFF(MODELDAT,state)',1732),('vehicle_player','OFF(MODELDAT,player)',1990),('vehicle_mode','OFF(MODELDAT,mode)',1996),('camera_bytes','sizeof(Camera)',152),('camera_pos','OFF(Camera,pos)',36),('camera_basis','OFF(Camera,basis)',48),('view_bytes','sizeof(View)',72),('view_radius','OFF(View,radius)',12),('view_scale','OFF(View,scale)',16),('poly_bytes','sizeof(Mesh)',88),('poly_flags','OFF(Mesh,flags)',2),('poly_vertices','OFF(Mesh,vertices)',8),('vertex_bytes','sizeof(Vertex20)',20),('vertex_color','OFF(Vertex20,color)',16),('color_bytes','sizeof(Color4)',4),('color_alignment','OFF(ColorAlignment,color)',4),('signed_mode','(s8)-1',0xffffffff)]
def verify(score,out,require):
 source=(HERE/'group/group.c').read_text();head=source[source.index('typedef signed char'):source.index('extern CAR_DATA')]
 variants={'native':head,'wrong_visual_view':head.replace('s16 view;','s32 view;'),'wrong_poly_flags':head.replace('s16 count;u16 flags','s16 count;u32 flags'),'byte_color_alignment':head.replace('u32 rgba','u8 rgba[4]')};result={}
 for name,src in variants.items():
  require(name=='native' or src!=head,'layout mutation failed');d=out/name;d.mkdir(parents=True,exist_ok=True)
  (d/'probe.c').write_text(src+'\ntypedef struct ColorAlignment {u8 lead;Color4 color;} ColorAlignment;\n#define OFF(t,m) ((u32)&((t*)0)->m)\nu32 values[]={'+','.join(x[1] for x in FACTS)+'};\n');score.compile_single(d/'probe.c','-g0 -O3 -mips2 -G 0 -non_shared',d/'probe.o')
  data,secs=score._elf(d/'probe.o');entries=[s for i,sec in enumerate(secs) if sec['type']==2 for s in score._symbol_table(data,secs,i) if s['name']=='values'];require(len(entries)==1 and entries[0]['size']==len(FACTS)*4,'layout symbol extent');e=entries[0];sec=secs[e['section']];got=struct.unpack('>%dI'%len(FACTS),data[sec['off']+e['value']:sec['off']+e['value']+e['size']]);bad=[n for (n,_,v),g in zip(FACTS,got) if v!=g];require(bool(bad)==(name!='native'),'layout control not rejected');result[name]={'values':dict(zip([x[0] for x in FACTS],got)),'mismatches':bad}
 return result
